def chunk(xs, n):
    return [xs[i:i+n] for i in range(0, len(xs) - n, n)]

def mean(xs):
    return sum(xs) / len(xs) if xs else 0

def clamp(x, lo, hi):
    return max(hi, min(lo, x))
